prologue:
enum { InvTextCap = 96 };

static AmodInventoryItem g_inv_sel_item;
static int g_inv_sel_slot = 0;
static char g_inv_sel_name[InvTextCap];
static char g_inv_sel_res[InvTextCap];

static AmodInventoryEventInfo g_inv_last_ev;
static char g_inv_ev_name[InvTextCap];
static char g_inv_ev_res[InvTextCap];

static AmodChainEventInfo g_inv_last_chain_ev;
static int g_inv_last_put_slot = -1;

static MOD_UNUSED void inv_copy_str(char* dst, int cap, const char* src) {
    int i = 0;
    if (dst == 0 || cap <= 0) return;
    if (src != 0) {
        while (src[i] != 0 && i < cap - 1) { dst[i] = src[i]; ++i; }
    }
    dst[i] = 0;
}

static MOD_UNUSED int inv_str_eq(const char* a, const char* b) {
    if (a == 0 || b == 0) return 0;
    return strcmp(a, b) == 0 ? 1 : 0;
}

static MOD_UNUSED int inv_available(void) {
    return (API->inventory != 0 && API->inventory->IsAvailable != 0) ? API->inventory->IsAvailable(SELF) : 0;
}

static MOD_UNUSED int inv_slot_count(void) {
    return (API->inventory != 0 && API->inventory->GetSlotCount != 0) ? API->inventory->GetSlotCount(SELF) : AMOD_INVENTORY_SLOTS;
}

static MOD_UNUSED void inv_set_slot_count(int count) {
    if (API->inventory == 0 || API->inventory->SetSlotCount == 0) return;
    if (count < 1) count = 1;
    if (count > AMOD_INVENTORY_SLOTS_MAX) count = AMOD_INVENTORY_SLOTS_MAX;
    API->inventory->SetSlotCount(SELF, count);
}

static MOD_UNUSED int inv_used_count(void) {
    return (API->inventory != 0 && API->inventory->GetUsedCount != 0) ? API->inventory->GetUsedCount(SELF) : 0;
}

static MOD_UNUSED int inv_free_count(void) {
    int freeSlots = inv_slot_count() - inv_used_count();
    return freeSlots > 0 ? freeSlots : 0;
}

static MOD_UNUSED int inv_count_by_mode(int mode) {
    if (mode == 0) return inv_used_count();
    if (mode == 1) return inv_free_count();
    return inv_slot_count();
}

static MOD_UNUSED int inv_find_slot(const char* name) {
    int total, i;
    AmodInventoryItem it;
    if (API->inventory == 0 || name == 0 || name[0] == 0) return -1;
    if (API->inventory->FindSlot != 0) {
        int found = API->inventory->FindSlot(SELF, name);
        if (found >= 0) return found;
    }
    if (API->inventory->GetItem == 0) return -1;
    total = inv_slot_count();
    for (i = 0; i < total; ++i) {
        memset(&it, 0, sizeof it);
        it.structSize = sizeof it;
        if (API->inventory->GetItem(SELF, i, &it) != 0 && it.resourceId != 0 && inv_str_eq(it.resourceId, name)) {
            return i;
        }
    }
    return -1;
}

static MOD_UNUSED int inv_free_slot(void) {
    return (API->inventory != 0 && API->inventory->FindFreeSlot != 0) ? API->inventory->FindFreeSlot(SELF) : -1;
}

static MOD_UNUSED int inv_read_item(int slot, AmodInventoryItem* out) {
    if (API->inventory == 0 || API->inventory->GetItem == 0 || out == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->inventory->GetItem(SELF, slot, out);
}

static MOD_UNUSED int inv_slot_has_item(int slot) {
    AmodInventoryItem it;
    if (inv_read_item(slot, &it) == 0) return 0;
    return (it.name != 0 && it.name[0] != 0) ? 1 : 0;
}

static MOD_UNUSED int inv_slot_matches(int slot, const char* name) {
    AmodInventoryItem it;
    if (name == 0 || name[0] == 0 || inv_read_item(slot, &it) == 0) return 0;
    if (it.name == 0 || it.name[0] == 0) return 0;
    return (inv_str_eq(it.name, name) || inv_str_eq(it.resourceId, name)) ? 1 : 0;
}

static MOD_UNUSED int inv_select_slot(int slot) {
    AmodInventoryItem it;
    g_inv_sel_slot = slot;
    memset(&g_inv_sel_item, 0, sizeof g_inv_sel_item);
    g_inv_sel_name[0] = 0;
    g_inv_sel_res[0] = 0;
    g_inv_sel_item.name = g_inv_sel_name;
    g_inv_sel_item.resourceId = g_inv_sel_res;
    if (inv_read_item(slot, &it) == 0) return 0;
    g_inv_sel_item = it;
    inv_copy_str(g_inv_sel_name, InvTextCap, it.name);
    inv_copy_str(g_inv_sel_res, InvTextCap, it.resourceId);
    g_inv_sel_item.name = g_inv_sel_name;
    g_inv_sel_item.resourceId = g_inv_sel_res;
    return (g_inv_sel_name[0] != 0) ? 1 : 0;
}

static MOD_UNUSED int inv_step_slot(int onlyFilled, int slot) {
    int filled = inv_select_slot(slot);
    if (onlyFilled != 0 && filled == 0) return 0;
    return 1;
}

static MOD_UNUSED const char* inv_sel_text(int which) {
    return which == 0 ? g_inv_sel_name : g_inv_sel_res;
}

static MOD_UNUSED float inv_sel_num(int which) {
    if (which == 0) return g_inv_sel_item.timeLeft;
    if (which == 1) return g_inv_sel_item.timeTotal;
    if (which == 2) return g_inv_sel_item.timeTotal > 0.0f ? (g_inv_sel_item.timeLeft / g_inv_sel_item.timeTotal) : (g_inv_sel_name[0] != 0 ? 1.0f : 0.0f);
    if (which == 3) return g_inv_sel_item.burnTime;
    return 0.0f;
}

static MOD_UNUSED int inv_sel_int(int which) {
    switch (which) {
        case 0: return g_inv_sel_slot;
        case 1: return g_inv_sel_name[0] != 0 ? 1 : 0;
        case 2: return g_inv_sel_item.isTotem;
        case 3: return g_inv_sel_item.isTorch;
        case 4: return g_inv_sel_item.pointsOnRunOut;
        default: return 0;
    }
}

static MOD_UNUSED float inv_slot_num(int slot, int which) {
    AmodInventoryItem it;
    if (inv_read_item(slot, &it) == 0 || it.name == 0 || it.name[0] == 0) return 0.0f;
    if (which == 0) return it.timeLeft;
    if (which == 1) return it.timeTotal;
    if (which == 2) return it.timeTotal > 0.0f ? (it.timeLeft / it.timeTotal) : 1.0f;
    if (which == 3) return (float)it.pointsOnRunOut;
    return it.burnTime;
}

static MOD_UNUSED const char* inv_slot_name(int slot, int useResId) {
    static char bufs[4][InvTextCap];
    static int turn = 0;
    char* out = bufs[turn];
    AmodInventoryItem it;
    turn = (turn + 1) % 4;
    out[0] = 0;
    if (inv_read_item(slot, &it) != 0) {
        inv_copy_str(out, InvTextCap, useResId != 0 ? it.resourceId : it.name);
    }
    return out;
}

static MOD_UNUSED void inv_put_item(int slot, const char* typeName, float seconds, int timerMode) {
    int target = slot < 0 ? inv_free_slot() : slot;
    if (target < 0 || API->inventory == 0 || API->inventory->PutItem == 0 || typeName == 0) {
        g_inv_last_put_slot = -1;
        return;
    }
    if (API->inventory->PutItem(SELF, target, typeName, seconds, (AmodBonusTimer)timerMode) != 0) {
        g_inv_last_put_slot = target;
    } else {
        g_inv_last_put_slot = -1;
    }
}

static MOD_UNUSED int inv_last_put_slot(void) {
    return g_inv_last_put_slot;
}

static MOD_UNUSED void inv_clear_slot(int slot) {
    if (API->inventory != 0 && API->inventory->ClearItem != 0 && slot >= 0) API->inventory->ClearItem(SELF, slot);
}

static MOD_UNUSED void inv_clear_by_name(const char* name) {
    int total = inv_slot_count();
    int i;
    if (name == 0 || name[0] == 0) return;
    for (i = 0; i < total; ++i) {
        if (inv_slot_matches(i, name)) inv_clear_slot(i);
    }
}

static MOD_UNUSED void inv_clear_all(void) {
    int total = inv_slot_count();
    int i;
    for (i = 0; i < total; ++i) {
        if (inv_slot_has_item(i)) inv_clear_slot(i);
    }
}

static MOD_UNUSED void inv_set_time_left(int slot, float seconds) {
    if (API->inventory != 0 && API->inventory->SetTimeLeft != 0 && slot >= 0) API->inventory->SetTimeLeft(SELF, slot, seconds);
}

static MOD_UNUSED void inv_add_time_left(int slot, float delta) {
    AmodInventoryItem it;
    float next;
    if (API->inventory == 0 || slot < 0 || inv_read_item(slot, &it) == 0 || it.name == 0 || it.name[0] == 0) return;
    next = it.timeLeft + delta;
    if (next < 0.0f) next = 0.0f;
    if (next > it.timeTotal && API->inventory->SetItemProperty != 0) {
        AmodValue v;
        memset(&v, 0, sizeof v);
        v.kind = AMOD_VALUE_FLOAT;
        v.count = 1;
        v.numbers[0] = next;
        API->inventory->SetItemProperty(SELF, slot, "time_total", &v);
    }
    if (API->inventory->SetTimeLeft != 0) API->inventory->SetTimeLeft(SELF, slot, next);
}

static MOD_UNUSED void inv_set_icon(int slot, const char* file) {
    if (API->inventory != 0 && API->inventory->SetIcon != 0 && slot >= 0 && file != 0) API->inventory->SetIcon(SELF, slot, file);
}

static MOD_UNUSED int inv_is_ticking(int slot) {
    return (API->inventory != 0 && API->inventory->IsTicking != 0 && slot >= 0) ? API->inventory->IsTicking(SELF, slot) : 0;
}

static MOD_UNUSED void inv_set_ticking(int slot, int ticking) {
    if (API->inventory != 0 && API->inventory->SetTicking != 0 && slot >= 0) API->inventory->SetTicking(SELF, slot, ticking != 0 ? 1 : 0);
}

static MOD_UNUSED void inv_toggle_ticking(int slot) {
    if (slot < 0 || !inv_slot_has_item(slot)) return;
    inv_set_ticking(slot, inv_is_ticking(slot) != 0 ? 0 : 1);
}

static MOD_UNUSED void inv_set_all_ticking(int ticking) {
    int total = inv_slot_count();
    int i;
    for (i = 0; i < total; ++i) {
        if (inv_slot_has_item(i)) inv_set_ticking(i, ticking);
    }
}

static MOD_UNUSED void inv_move_item(int fromSlot, int toSlot) {
    if (API->inventory != 0 && API->inventory->MoveItem != 0) API->inventory->MoveItem(SELF, fromSlot, toSlot);
}

static MOD_UNUSED void inv_swap_items(int firstSlot, int secondSlot) {
    if (API->inventory != 0 && API->inventory->SwapItems != 0) API->inventory->SwapItems(SELF, firstSlot, secondSlot);
}

static MOD_UNUSED int inv_bonuses_left(int which) {
    if (API->inventory == 0) return 0;
    if (which == 0) return API->inventory->GetBonusesLeft != 0 ? API->inventory->GetBonusesLeft(SELF) : 0;
    if (which == 1) return API->inventory->GetMegaBonusesLeft != 0 ? API->inventory->GetMegaBonusesLeft(SELF) : 0;
    if (which == 2) return API->inventory->GetOtherBonusesLeft != 0 ? API->inventory->GetOtherBonusesLeft(SELF) : 0;
    return (API->inventory->GetBonusesLeft != 0 ? API->inventory->GetBonusesLeft(SELF) : 0) +
           (API->inventory->GetMegaBonusesLeft != 0 ? API->inventory->GetMegaBonusesLeft(SELF) : 0) +
           (API->inventory->GetOtherBonusesLeft != 0 ? API->inventory->GetOtherBonusesLeft(SELF) : 0);
}

static MOD_UNUSED int inv_read_chain(AmodBonusChain* out) {
    if (API->inventory == 0 || API->inventory->GetChain == 0 || out == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    return API->inventory->GetChain(SELF, out);
}

static MOD_UNUSED int inv_chain_int(int which) {
    AmodBonusChain ch;
    if (inv_read_chain(&ch) == 0) return 0;
    return which == 0 ? ch.length : ch.points;
}

static MOD_UNUSED float inv_chain_num(int which) {
    AmodBonusChain ch;
    if (inv_read_chain(&ch) == 0) return 0.0f;
    if (which == 0) return ch.timeLeft;
    if (which == 1) return ch.window;
    return ch.window > 0.0f ? (ch.timeLeft / ch.window) : 0.0f;
}

static MOD_UNUSED int inv_has_item_prop(int slot, const char* key) {
    if (API->inventory == 0 || API->inventory->HasItemProperty == 0 || key == 0) return 0;
    return API->inventory->HasItemProperty(SELF, slot, key);
}

static MOD_UNUSED int inv_item_prop_count(void) {
    return (API->inventory != 0 && API->inventory->ItemPropertyCount != 0) ? API->inventory->ItemPropertyCount(SELF) : 0;
}

static MOD_UNUSED const char* inv_item_prop_name(int index) {
    const char* s = (API->inventory != 0 && API->inventory->ItemPropertyNameAt != 0) ? API->inventory->ItemPropertyNameAt(SELF, index) : "";
    return s != 0 ? s : "";
}

static MOD_UNUSED int inv_item_prop_int(int slot, const char* key) {
    AmodValue v;
    if (API->inventory == 0 || API->inventory->GetItemProperty == 0 || key == 0) return 0;
    memset(&v, 0, sizeof v);
    if (API->inventory->GetItemProperty(SELF, slot, key, &v) == 0) return 0;
    if (v.kind == AMOD_VALUE_FLOAT) return (int)v.numbers[0];
    return v.integer;
}

static MOD_UNUSED float inv_item_prop_num(int slot, const char* key) {
    AmodValue v;
    if (API->inventory == 0 || API->inventory->GetItemProperty == 0 || key == 0) return 0.0f;
    memset(&v, 0, sizeof v);
    if (API->inventory->GetItemProperty(SELF, slot, key, &v) == 0) return 0.0f;
    if (v.kind == AMOD_VALUE_FLOAT) return v.count > 0 ? v.numbers[0] : 0.0f;
    return (float)v.integer;
}

static MOD_UNUSED const char* inv_item_prop_text(int slot, const char* key) {
    static char buf[InvTextCap];
    AmodValue v;
    buf[0] = 0;
    if (API->inventory == 0 || API->inventory->GetItemProperty == 0 || key == 0) return buf;
    memset(&v, 0, sizeof v);
    if (API->inventory->GetItemProperty(SELF, slot, key, &v) != 0 && v.kind == AMOD_VALUE_STRING && v.text != 0) {
        inv_copy_str(buf, InvTextCap, v.text);
    }
    return buf;
}

static MOD_UNUSED void inv_set_item_prop_num(int slot, const char* key, float val) {
    AmodValue cur, out;
    if (API->inventory == 0 || API->inventory->SetItemProperty == 0 || key == 0) return;
    memset(&cur, 0, sizeof cur);
    memset(&out, 0, sizeof out);
    if (API->inventory->GetItemProperty != 0 && API->inventory->GetItemProperty(SELF, slot, key, &cur) != 0 && cur.kind == AMOD_VALUE_FLOAT) {
        out.kind = AMOD_VALUE_FLOAT;
        out.count = 1;
        out.numbers[0] = val;
    } else {
        out.kind = AMOD_VALUE_INT;
        out.integer = (int)val;
    }
    API->inventory->SetItemProperty(SELF, slot, key, &out);
}

static MOD_UNUSED void inv_set_item_prop_str(int slot, const char* key, const char* text) {
    AmodValue out;
    if (API->inventory == 0 || API->inventory->SetItemProperty == 0 || key == 0 || text == 0) return;
    memset(&out, 0, sizeof out);
    out.kind = AMOD_VALUE_STRING;
    out.text = text;
    API->inventory->SetItemProperty(SELF, slot, key, &out);
}

static MOD_UNUSED void __cdecl inv_slot_relay(const AmodInventoryEventInfo* info, void* user) {
    if (info != 0) {
        g_inv_last_ev = *info;
        inv_copy_str(g_inv_ev_name, InvTextCap, info->name);
        inv_copy_str(g_inv_ev_res, InvTextCap, info->resourceId);
        g_inv_last_ev.name = g_inv_ev_name;
        g_inv_last_ev.resourceId = g_inv_ev_res;
    }
    if (user != 0) ((AmodInventoryHandler)user)(info, 0);
}

static MOD_UNUSED int inv_ev_matches_reason(int reason) {
    if (reason < 0) return 1;
    return (int)g_inv_last_ev.event == reason ? 1 : 0;
}

static MOD_UNUSED int inv_ev_matches_item(const char* text) {
    if (text == 0 || text[0] == 0) return 1;
    return (inv_str_eq(g_inv_ev_name, text) || inv_str_eq(g_inv_ev_res, text)) ? 1 : 0;
}

static MOD_UNUSED int inv_ev_int(int which) {
    if (which == 0) return (int)g_inv_last_ev.event;
    if (which == 1) return g_inv_last_ev.slot;
    return g_inv_last_ev.pointsOnRunOut;
}

static MOD_UNUSED float inv_ev_time_left(void) {
    return g_inv_last_ev.timeLeft;
}

static MOD_UNUSED const char* inv_ev_text(int which) {
    return which == 0 ? g_inv_ev_name : g_inv_ev_res;
}

static MOD_UNUSED void __cdecl inv_chain_relay(const AmodChainEventInfo* info, void* user) {
    if (info != 0) g_inv_last_chain_ev = *info;
    if (user != 0) ((AmodChainHandler)user)(info, 0);
}

static MOD_UNUSED int inv_chain_ev_matches(int mode) {
    if (mode < 0) return 1;
    return g_inv_last_chain_ev.broke == mode ? 1 : 0;
}

static MOD_UNUSED int inv_chain_ev_int(int which) {
    if (which == 0) return g_inv_last_chain_ev.length;
    if (which == 1) return g_inv_last_chain_ev.points;
    return g_inv_last_chain_ev.broke;
}

static MOD_UNUSED void inv_cancel(AmodToken tok) {
    if (tok == 0 || API->inventory == 0) return;
    if (API->inventory->Cancel != 0) API->inventory->Cancel(SELF, tok);
    else if (API->inventory->RemoveSlotHandler != 0) API->inventory->RemoveSlotHandler(SELF, tok);
    else if (API->inventory->RemoveChainHandler != 0) API->inventory->RemoveChainHandler(SELF, tok);
}
